import{_ as o,o as d,c as a,a3 as t}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Calendar — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/calendar"}]]},"headers":[],"relativePath":"developer-guide/calendar.md","filePath":"developer-guide/calendar.md","lastUpdated":1791463208000}'),c={name:"developer-guide/calendar.md"};function n(r,e,s,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="calendar-—-developer-guide" tabindex="-1">Calendar — Developer Guide <a class="header-anchor" href="#calendar-—-developer-guide" aria-label="Permalink to &quot;Calendar — Developer Guide&quot;">​</a></h1><blockquote><p><strong>Status: Implemented (v1 + 1.9.0 named calendars)</strong><br> Meetings depends on Calendar (required) and projects via <code>upsertFromSource</code>. No calendar <code>assignee_id</code> field.</p></blockquote><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td><code>calendar_events</code> table / CRUD / Week·Day·Month·Agenda UI</td><td>Calendar module</td></tr><tr><td>Meeting booking, host assignment, Zoom/Meet, reminders</td><td><a href="/developer-guide/meetings">Meetings</a> module (calls <code>CalendarEventService</code>)</td></tr></tbody></table><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h2><p><code>App\\Models\\CalendarEvent</code> — <code>BelongsToTenant</code>, <code>LogsActivity</code>, <code>SoftDeletes</code>.</p><p>Key fields: <code>organizer_id</code>, <code>starts_at</code>, <code>ends_at</code>, <code>all_day</code>, <code>timezone</code>, <code>status</code> (<code>scheduled</code>|<code>cancelled</code>), <code>source</code> (<code>manual</code>|<code>meeting</code>|<code>project</code>|<code>task</code>|<code>lead</code>), nullable <code>source_type</code>/<code>source_id</code> (Meetings uses morph alias <code>meeting</code>; Projects/Tasks/Leads use <code>project</code> / <code>task</code> / <code>lead</code>), nullable <code>external_provider</code> (<code>google</code>|<code>microsoft</code>) / <code>external_event_id</code> (Calendar sync mapping — <strong>1.4.0</strong>), nullable <code>calendar_id</code> (named team/department calendar — <strong>1.9.0</strong>; <code>null</code> = personal, unchanged default).</p><p><strong>Excluded:</strong> <code>assignee_id</code> field (overlays push via <code>shouldPushToProvider()</code> — see sync sections below).</p><h2 id="visibility" tabindex="-1">Visibility <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;Visibility&quot;">​</a></h2><ul><li>Without <code>calendar.view_all</code>: <code>organizer_id = actor</code> <strong>or</strong> meeting projection where the actor is a <code>meeting_attendees.user_id</code> row for <code>source_type=meeting</code> / <code>source_id</code> <strong>or</strong> the event belongs to a named calendar the actor may see (see <strong>Named calendars</strong> below)</li><li>With <code>calendar.view_all</code> or Owner superadmin: all tenant events</li><li>Update / cancel / delete remain organizer-only (or <code>view_all</code> / superadmin) — invitees and named-calendar members are read-only unless they are also the organizer</li><li>Resource includes <code>read_only: true</code> when the viewer is not the organizer and lacks <code>view_all</code></li><li><code>POST</code> always sets <code>organizer_id</code> to the authenticated user; <code>organizer_id</code> / <code>assignee_id</code> are <strong>prohibited</strong> on requests; <code>calendar_id</code> is optional (defaults to personal)</li></ul><h2 id="service-contract-meetings-ready" tabindex="-1">Service contract (Meetings-ready) <a class="header-anchor" href="#service-contract-meetings-ready" aria-label="Permalink to &quot;Service contract (Meetings-ready)&quot;">​</a></h2><p><code>App\\Services\\Tenant\\CalendarEventService</code>:</p><ul><li><code>createForOrganizer</code>, <code>update</code>, <code>cancel</code>, <code>delete</code></li><li><code>listInRange</code>, <code>upcoming</code></li><li><code>upsertFromSource</code> — used by Meetings, Projects, Tasks, and Leads; unused by Calendar UI for create</li></ul><h2 id="overlays-1-1-0" tabindex="-1">Overlays (1.1.0) <a class="header-anchor" href="#overlays-1-1-0" aria-label="Permalink to &quot;Overlays (1.1.0)&quot;">​</a></h2><p>When Calendar is entitled:</p><table tabindex="0"><thead><tr><th>Source</th><th>Projector</th><th>Projection</th></tr></thead><tbody><tr><td><code>meeting</code></td><td>Meetings</td><td>Host event</td></tr><tr><td><code>project</code></td><td>Projects</td><td>All-day on <code>starts_on</code> / <code>ends_on</code></td></tr><tr><td><code>task</code></td><td>Tasks</td><td>Timed window from <code>due_at</code> (+1h); cleared when completed/cancelled/no due</td></tr><tr><td><code>lead</code></td><td>Leads</td><td>Timed window from <code>next_follow_up_at</code> (+1h); cleared when converted/closed/archived/no follow-up</td></tr></tbody></table><p>Catalog version <strong>1.1.0</strong> (overlays). <strong>1.2.0</strong> invitee ACL. <strong>1.3.0</strong> shares. <strong>1.4.0</strong> OAuth push. <strong>1.5.0</strong> Meeting/Task/Lead overlay push. <strong>1.6.0</strong> inbound pull (<code>source=external</code>). <strong>1.7.0</strong> Project/Contact/Company overlay push. <strong>1.8.0</strong> webhook-driven near real-time inbound. <strong>1.9.0</strong> named team/department calendars. Pest: overlay + push + inbound + watch/webhook + <code>NamedCalendarTest.php</code>.</p><h2 id="google-outlook-sync-1-4-0–1-7-0" tabindex="-1">Google / Outlook sync (1.4.0–1.7.0) <a class="header-anchor" href="#google-outlook-sync-1-4-0–1-7-0" aria-label="Permalink to &quot;Google / Outlook sync (1.4.0–1.7.0)&quot;">​</a></h2><p>Per-user push for <strong>manual</strong> + Meeting/Task/Lead/Project/Contact/Company (<code>shouldPushToProvider()</code>; External never). <strong>1.6.0</strong> inbound: <code>listEvents</code> → ingest as <code>External</code> (read-only; never pushed). EloSync-owned mappings skipped on pull. <code>POST /calendar/integrations/sync</code> + hourly <code>calendar:pull-provider-events</code>.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td>Config</td><td><code>config/calendar-sync.php</code> — <code>google.client_id/secret</code>, <code>microsoft.client_id/secret/tenant</code>, <code>oauth_callback_path</code>, <code>providers.fake</code></td></tr><tr><td>Connection model</td><td><code>App\\Models\\CalendarProviderConnection</code> (<code>BelongsToTenant</code>, <code>SoftDeletes</code>) — <code>tenant_id</code>, <code>user_id</code>, <code>provider</code> (<code>CalendarSyncProviderEnum</code>: <code>google</code>|<code>microsoft</code>), encrypted <code>access_token</code>/<code>refresh_token</code>, <code>expires_at</code>, <code>status</code> (<code>CalendarProviderConnectionStatusEnum</code>), <code>external_calendar_id</code>, <code>meta</code> json</td></tr><tr><td>Providers</td><td><code>App\\Services\\CalendarSync\\Providers\\GoogleCalendarProvider</code>, <code>MicrosoftCalendarProvider</code> — implement <code>CalendarSyncProviderInterface</code> (<code>authorizationUrl</code>, <code>exchangeCode</code>, <code>refreshAccessToken</code>, <code>pushEvent</code>, <code>updateEvent</code>, <code>cancelEvent</code>); driver resolution via <code>CalendarSyncProviderRegistry</code></td></tr><tr><td>Orchestration</td><td><code>App\\Services\\Tenant\\CalendarSyncService</code> — <code>statusForUser</code>, <code>hasPlatformCredentials</code>, <code>authorizationUrl</code>, <code>disconnect</code>, <code>pushEvent($event, $action)</code></td></tr><tr><td>Controller</td><td><code>App\\Http\\Controllers\\Tenant\\Api\\V1\\CalendarIntegrationController</code> — <code>index</code> (status), <code>authorizeProvider</code> (redirect URL), <code>disconnect</code>; web OAuth <code>callback</code> lives on <code>routes/web.php</code> (no tenant auth on the callback route itself, nonce-verified)</td></tr><tr><td>Queue job</td><td><code>App\\Jobs\\Tenant\\PushCalendarEventToProviderJob</code> (<code>calendar-sync</code> queue, <code>tries=3</code>, <code>backoff=[5,30,120]</code>) — dispatched from <code>CalendarEventSubscriber</code> on create/update/cancel/delete when <code>source-&gt;shouldPushToProvider()</code> (manual + meeting + task + lead + project + contact + company; not external)</td></tr></tbody></table><p>Routes (tenant, <code>can:calendar.manage_integrations</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /calendar/integrations              status per provider for the authenticated user</span></span>
<span class="line"><span>GET    /calendar/integrations/{provider}/authorize   OAuth authorize URL</span></span>
<span class="line"><span>DELETE /calendar/integrations/{provider}   disconnect</span></span></code></pre></div><p>Web (platform, no tenant scope on the route itself):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/oauth/calendar-sync/{provider}/callback   OAuth callback, redirects to \`/#/calendar?integrations=…\`</span></span></code></pre></div><p><strong>Push behavior:</strong></p><ul><li>Pushes to <strong>every</strong> connected provider for the event&#39;s organizer (a user may connect both Google and Microsoft).</li><li><code>created</code> always calls <code>pushEvent()</code> on the driver (never <code>updateEvent()</code>), even if <code>external_event_id</code> is already set from a different provider.</li><li><code>updated</code> calls <code>updateEvent()</code> only when the connection&#39;s provider matches the currently-stored <code>external_provider</code>; otherwise it treats the connection as unsynced and calls <code>pushEvent()</code>.</li><li><code>cancelled</code>/<code>deleted</code> calls <code>cancelEvent()</code> only against the mapped provider.</li><li><strong>Known Phase-1 limitation:</strong> <code>external_provider</code>/<code>external_event_id</code> on <code>calendar_events</code> is a single-value mapping, not per-provider. If a user has both Google and Microsoft connected, only the last-written provider&#39;s ID is persisted, so update/cancel is only guaranteed to reach the most-recently-synced provider — see the <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">production readiness audit</a>.</li><li>Failures are caught, <code>report()</code>-ed, and logged (<code>calendar-sync.push-failed</code>) — a broken provider connection never blocks calendar writes (mirrors <code>LiveChatConversationService</code>&#39;s soft-fail pattern).</li><li><code>GoogleCalendarProvider</code>/<code>MicrosoftCalendarProvider</code> expose a <code>fake()</code> escape hatch that is forced on in <code>testing</code> (and never enabled in <code>production</code>), so Pest never makes real HTTP calls even without <code>Http::fake()</code>.</li></ul><p><strong>Excluded (this section):</strong> <code>assignee_id</code>, Customer Portal calendar visibility. Named calendars, inbound pull, and webhooks are covered in later sections.</p><h2 id="webhook-driven-inbound-sync-1-8-0" tabindex="-1">Webhook-driven inbound sync (1.8.0) <a class="header-anchor" href="#webhook-driven-inbound-sync-1-8-0" aria-label="Permalink to &quot;Webhook-driven inbound sync (1.8.0)&quot;">​</a></h2><p>Each connected account also gets a provider push-notification watch so inbound changes arrive near real-time instead of waiting for the hourly pull.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td>Config</td><td><code>config/calendar-sync.php</code> — <code>webhook_callback_path</code>, <code>watch.microsoft_ttl_minutes</code> (Graph <code>me/events</code> subscriptions cap at ~4230 min / 2.94 days), <code>watch.renew_within_days</code></td></tr><tr><td>Watch state</td><td><code>calendar_provider_connections.meta.watch</code> — <code>watch_id</code> (Google channel id / Graph subscription id), <code>resource_id</code> (Google only), <code>client_state</code> (Google channel token / Graph <code>clientState</code>, used to verify inbound requests), <code>expires_at</code>; <code>external_calendar_id</code> set alongside it (<code>primary</code> for Google)</td></tr><tr><td>Provider contract</td><td><code>CalendarSyncProviderInterface::createWatch/renewWatch/stopWatch</code> — Google: POST <code>.../events/watch</code> then <code>channels/stop</code>; Microsoft: POST/PATCH/DELETE <code>https://graph.microsoft.com/v1.0/subscriptions</code>. Same <code>fake()</code> escape hatch (forced on in <code>testing</code>) as <code>listEvents</code></td></tr><tr><td>Orchestration</td><td><code>CalendarSyncService::ensureWatch</code> (no-op unless missing/near expiry), <code>renewWatch</code>, <code>stopWatch</code> (called from <code>disconnect()</code>), <code>resolveConnectionByWatch</code> (central-context lookup for the webhook) — all soft-fail: <code>report()</code> + <code>Log::warning(&#39;calendar-sync.watch-*-failed&#39;, …)</code>, never thrown</td></tr><tr><td>Webhook controller</td><td><code>App\\Http\\Controllers\\Central\\CalendarSyncWebhookController</code> — Microsoft <code>?validationToken=</code> handshake (plain-text echo); Google verifies <code>X-Goog-Channel-Token</code> against <code>meta.watch.client_state</code> and ignores the initial <code>X-Goog-Resource-State: sync</code> message; Microsoft verifies each notification&#39;s <code>clientState</code>. Always responds <code>{&quot;received&quot;: true}</code> and never surfaces errors to the provider</td></tr><tr><td>Renewal</td><td><code>calendar:renew-provider-watches</code> (daily) — renews any watch inside <code>watch.renew_within_days</code> of <code>expires_at</code></td></tr></tbody></table><p>Routes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /webhooks/calendar-sync/{provider}   Google / Microsoft push notifications (no tenant scope on the route itself; connection resolved by watch id)</span></span></code></pre></div><p>Watch is created on OAuth connect success and on <strong>Sync now</strong> (<code>CalendarIntegrationController::callback</code>/<code>sync</code>). The watch id is unique per provider across every tenant (single-database tenancy), so the webhook controller resolves the owning connection without any tenant context — the same model used by the OAuth callback. Hourly <code>calendar:pull-provider-events</code> remains the backstop for anything the webhook misses (provider outage, missed renewal, etc).</p><p><strong>Excluded:</strong> Microsoft Graph lifecycle-notification endpoint (reminder-only subscriptions renew via the daily command instead).</p><h2 id="named-team-department-calendars-1-9-0" tabindex="-1">Named team/department calendars (1.9.0) <a class="header-anchor" href="#named-team-department-calendars-1-9-0" aria-label="Permalink to &quot;Named team/department calendars (1.9.0)&quot;">​</a></h2><p>Named calendars let a tenant create shared calendars (e.g. &quot;Sales team&quot;, &quot;Ops&quot;) that are visible to more than just the organizer, without touching Personal calendar behavior (<code>calendar_id = null</code>).</p><table tabindex="0"><thead><tr><th>Concept</th><th>Owner</th></tr></thead><tbody><tr><td>Model</td><td><code>App\\Models\\Calendar</code> (<code>BelongsToTenant</code>, <code>LogsActivity</code>, <code>SoftDeletes</code>) — <code>name</code>, unique-per-tenant <code>slug</code>, nullable <code>department_id</code> (soft dependency — only settable when the <code>departments</code> module is entitled for the tenant), nullable <code>created_by</code></td></tr><tr><td>Service</td><td><code>App\\Services\\Tenant\\CalendarService</code> — CRUD, <code>canManageAll()</code> (superadmin | <code>calendar.view_all</code> | <code>calendar.manage_calendars</code>), <code>isMember()</code> (creator, or department manager/member when departments is entitled), <code>assertCanPostEvents()</code></td></tr><tr><td>Policy</td><td><code>App\\Policies\\CalendarPolicy</code> — <code>viewAny</code>/<code>view</code> need <code>calendar.view</code>; <code>create</code>/<code>update</code>/<code>delete</code> need <code>calendar.manage_calendars</code></td></tr><tr><td>Resource</td><td><code>App\\Http\\Resources\\Tenant\\Api\\V1\\Calendar\\CalendarResource</code></td></tr></tbody></table><p>Routes (tenant, <code>module:calendar</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /calendar/calendars            can:calendar.view        — list calendars visible to the actor</span></span>
<span class="line"><span>POST   /calendar/calendars            can:calendar.manage_calendars</span></span>
<span class="line"><span>PUT    /calendar/calendars/{calendar} can:calendar.manage_calendars</span></span>
<span class="line"><span>DELETE /calendar/calendars/{calendar} can:calendar.manage_calendars</span></span></code></pre></div><p><strong>Visibility</strong> (<code>CalendarEventService::applyVisibilityScope</code>, mirrored in <code>CalendarEventPolicy::isNamedCalendarVisible</code> for single-event checks): an event with <code>calendar_id</code> set is visible to the calendar&#39;s creator, to department members/manager when <code>department_id</code> is set <strong>and</strong> the <code>departments</code> module is currently entitled for the tenant, and to anyone with <code>calendar.view_all</code>. Department-based visibility is re-checked live — uninstalling Departments stops department-based sharing without deleting the calendar or its events; creator visibility is unaffected by entitlement.</p><p><strong>Posting events:</strong> creating or updating an event with a non-null <code>calendar_id</code> still requires <code>calendar.create</code>, and additionally requires membership in that calendar (creator, department member/manager, or an admin-level override via <code>canManageAll()</code>) — enforced in <code>CalendarEventService::resolveCalendarId()</code>.</p><p><strong>Overlays stay personal:</strong> <code>upsertFromSource()</code> (Meetings/Projects/Tasks/Leads) never sets <code>calendar_id</code>; projected events are always personal to the organizer, matching provider push which keys off <code>organizer_id</code>/<code>source</code> only.</p><p>Catalog <strong>calendar 1.8.0 → 1.9.0</strong> (migrate-only + CatalogSeeder). New permission <code>calendar.manage_calendars</code> (admin/manager defaults, additive via <code>TenantPermissionSynchronizer</code>). Pest: <code>tests/Feature/Tenant/Calendar/NamedCalendarTest.php</code>.</p><p><strong>Excluded:</strong> named-calendar provider push/watches, per-calendar notification digests.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Location</th></tr></thead><tbody><tr><td>Page</td><td><code>src/pages/calendar/calendar-page.tsx</code></td></tr><tr><td>Time grid (Week/Day + DnD)</td><td><code>src/pages/calendar/calendar-time-grid.tsx</code> (<code>@dnd-kit/core</code>)</td></tr><tr><td>Form / detail</td><td><code>calendar-event-form-dialog.tsx</code>, <code>calendar-event-detail-sheet.tsx</code></td></tr><tr><td>Named calendars (create/edit/delete)</td><td><code>calendar-manager-dialog.tsx</code> — gated by <code>calendar.manage_calendars</code>; department picker soft-gated by <code>hasModule(&#39;departments&#39;)</code></td></tr><tr><td>Datetime helpers</td><td><code>src/lib/datetime.ts</code> (<code>appTimezone</code>, <code>moveEventToSlot</code>, …)</td></tr><tr><td>API</td><td><code>calendarService</code> in <code>src/api/services.ts</code> (<code>calendarService.calendars.*</code> for named calendars)</td></tr><tr><td>E2E</td><td><code>e2e/tests/calendar/</code>, <code>npm run test:e2e:calendar</code></td></tr></tbody></table><p>Drag-and-drop on Week/Day calls <code>PUT /calendar/events/{id}</code> with new <code>starts_at</code> / <code>ends_at</code> (15-minute snap). Display and inputs use the workspace timezone from settings. <code>starts_at</code> / <code>ends_at</code> / <code>cancelled_at</code> use <code>UtcDateTime</code> + <code>UtcIso</code> so non-UTC workspace timezones do not shift absolute instants.</p><p>The event list/filter chips (<strong>All</strong> / <strong>Personal</strong> / one per named calendar) pass <code>calendar_id</code> (<code>&#39;personal&#39;</code> or a calendar id) through to <code>GET /calendar/events</code>, server-filtered the same way as the visibility scope.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Configured in <code>config/tenant-permissions.php</code> + default role map:</p><table tabindex="0"><thead><tr><th>Role</th><th>Grants</th></tr></thead><tbody><tr><td>admin</td><td>all including <code>view_all</code>, <code>manage_integrations</code>, <code>manage_calendars</code></td></tr><tr><td>manager</td><td>all except <code>delete</code>; includes <code>view_all</code>, <code>manage_calendars</code>; no <code>manage_integrations</code></td></tr><tr><td>staff</td><td><code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code> (own only via policy); no <code>view_all</code>, no <code>manage_integrations</code>, no <code>manage_calendars</code></td></tr></tbody></table><p><code>manage_integrations</code> (Calendar sync connect/disconnect) is admin-only, mirroring Meetings&#39; <code>manage_integrations</code>. <code>manage_calendars</code> (named calendar CRUD) is granted to admin <strong>and</strong> manager by default.</p><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>Migrate-only:</p><ul><li><code>2026_07_20_230514_create_calendar_events_table.php</code></li><li><code>2026_07_21_040000_register_calendar_module.php</code></li><li><code>2026_07_21_040001_add_calendar_permissions.php</code></li><li><code>2026_09_30_150000_create_calendar_provider_connections_table.php</code></li><li><code>2026_09_30_150001_add_external_provider_to_calendar_events_table.php</code> (adds <code>external_provider</code>/<code>external_event_id</code>, unique index on tenant+provider+external id)</li><li><code>2026_09_30_150002_add_calendar_manage_integrations_permission.php</code></li><li><code>2026_09_30_150003_bump_calendar_module_version_to_1_4_0.php</code></li><li>…through <code>2026_10_08_160000_bump_calendar_module_to_1_8_0.php</code> (webhook-driven inbound sync; no schema change — reuses <code>calendar_provider_connections.meta</code>)</li><li><code>2026_10_08_163000_create_calendars_table.php</code>, <code>2026_10_08_163500_add_calendar_id_to_calendar_events_table.php</code>, <code>2026_10_08_164000_add_calendar_manage_calendars_permission.php</code>, <code>2026_10_08_170000_bump_calendar_module_to_1_9_0.php</code> (named team/department calendars)</li></ul><p>Also listed in <code>CatalogSeeder</code> for fresh/local/CI.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p><code>DashboardWidgetService</code> registers widget id <code>calendar</code> (upcoming events), gated by <code>module:calendar</code> + <code>calendar.view</code>, scoped by <code>calendar.view_all</code>.</p><h2 id="audit-activity" tabindex="-1">Audit &amp; activity <a class="header-anchor" href="#audit-activity" aria-label="Permalink to &quot;Audit &amp; activity&quot;">​</a></h2><ul><li>Spatie <code>LogsActivity</code> on <code>CalendarEvent</code> records attribute changes.</li><li><code>App\\Listeners\\CalendarEventSubscriber</code> (registered in <code>AppServiceProvider</code>) writes platform audit entries (<code>activity</code> log name <code>platform</code>) for <code>calendar_event_created|updated|cancelled|deleted</code>, mirroring Leads/Tasks/Communication Templates.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>Pest: <code>tests/Feature/Tenant/Calendar/CalendarEventTest.php</code>, <code>MeetingInviteeCalendarAclTest.php</code>, <code>CalendarIntegrationTest.php</code>, <code>CalendarEventProviderPushTest.php</code>, <code>CalendarProviderWatchTest.php</code>, <code>CalendarWebhookInboundSyncTest.php</code>, <code>NamedCalendarTest.php</code></li><li>Playwright: <code>npm run test:e2e:calendar</code> (includes invitee view-only, <code>calendar-overlay-sync.spec.ts</code>, and a named-calendar case in <code>calendar.workflow.spec.ts</code>)</li></ul><h2 id="explicit-non-goals" tabindex="-1">Explicit non-goals <a class="header-anchor" href="#explicit-non-goals" aria-label="Permalink to &quot;Explicit non-goals&quot;">​</a></h2><p><code>assignee_id</code> field, named-calendar provider sync/watches (team events still push via each event’s <code>organizer_id</code> OAuth connection), per-provider <code>external_event_id</code> mapping (single-value today — see the <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">1.4.0 production readiness audit</a>), Customer Portal calendar visibility. Meetings/Zoom/Meet live in the Meetings module.</p>`,64)])])}const g=o(c,[["render",n]]);export{u as __pageData,g as default};
